def daemons():
    declared = yaml.safe_load(open(os.path.join(HERE, 'daemon_dispositions.yaml'), encoding='utf-8'))['daemons']
    names = [n for _, n in DAEMON_ORDER]
    assert sorted(names) == sorted(declared), ('the daemon order and the dispositions disagree', sorted(set(names) ^ set(declared)))
    return [getattr(sys.modules[m], n) for m, n in DAEMON_ORDER]


def registry_map():
    """THE ONE WHO-IS-WHO: logic/corpus/entity_registry.yaml's members scoped to the step-9 scenes -> the entity id"""
    d = yaml.safe_load(open('<repo-old>/logic/corpus/entity_registry.yaml', encoding='utf-8'))
    m = {}
    for ent in d['entities']:
        for mem in ent.get('members') or []:
            if 'step9-scenes' in (mem.get('units') or []):
                m[mem['token']] = ent['id']
    return m


